import{_ as t,a as r,c as d,ac as a}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"Redis Sorted Set（有序集合） · 1. 定位：解决什么问题至2. 命令速查与示例","description":"排行榜、在线状态、匹配与延迟任务，包括基本操作、适用场景和使用边界。","frontmatter":{"title":"Redis Sorted Set（有序集合） · 1. 定位：解决什么问题至2. 命令速查与示例","description":"排行榜、在线状态、匹配与延迟任务，包括基本操作、适用场景和使用边界。","splitFrom":"middleware/redis/plus/subjects/sorted-set.md","showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"Redis Sorted Set（有序集合）","summary":"排行榜、在线状态、匹配与延迟任务，包括基本操作、适用场景和使用边界。","status":"active","related":[{"title":"Redis 操作与命令","link":"/middleware/redis/plus/ecosystem/redis-general-general","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 数据类型命令速查","link":"/middleware/redis/plus/subjects/redis-data-cmd","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 游戏与通用后端场景","link":"/middleware/redis/pro/practice/game-scenarios","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 持久化：RDB、AOF 与独立恢复","link":"/middleware/redis/persistence-and-recovery","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":{"text":"Redis Sorted Set（有序集合）","link":"/middleware/redis/plus/subjects/sorted-set"},"next":{"text":"Redis Sorted Set（有序集合） · 旧版兼容命令至6. 过期、持久化与生命周期","link":"/middleware/redis/plus/subjects/sorted-set-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Redis Sorted Set（有序集合）","link":"/middleware/redis/plus/subjects/sorted-set"},"next":{"text":"Redis Sorted Set（有序集合） · 旧版兼容命令至6. 过期、持久化与生命周期","link":"/middleware/redis/plus/subjects/sorted-set-part-02"}},"headers":[],"relativePath":"middleware/redis/plus/subjects/sorted-set-part-01.md","filePath":"middleware/redis/plus/subjects/sorted-set-part-01.md"}'),s={name:"middleware/redis/plus/subjects/sorted-set-part-01.md"};function o(n,e,i,l,c,b){return r(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="redis-sorted-set-有序集合-·-1-定位-解决什么问题至2-命令速查与示例" tabindex="-1">Redis Sorted Set（有序集合） · 1. 定位：解决什么问题至2. 命令速查与示例 <a class="header-anchor" href="#redis-sorted-set-有序集合-·-1-定位-解决什么问题至2-命令速查与示例" aria-label="Permalink to &quot;Redis Sorted Set（有序集合） · 1. 定位：解决什么问题至2. 命令速查与示例&quot;">​</a></h1><p><a href="/middleware/redis/plus/subjects/sorted-set">返回分篇目录</a></p><p>本文按 Redis 8.2.10 核对编码与配置默认值；命令的引入版本另行标注。生产配置可能不同，可通过 CONFIG GET 查询。示例面向独立实验服务，运行结果和内存数字未在本次实测。</p><h2 id="sorted-set" tabindex="-1">Redis Sorted Set（有序集合） <a class="header-anchor" href="#sorted-set" aria-label="Permalink to &quot;Redis Sorted Set（有序集合） {#sorted-set}&quot;">​</a></h2><p>本文按 Redis 8.2.10 核对编码与配置默认值；命令的引入版本另行标注。生产配置可能不同，可通过 CONFIG GET 查询。示例面向独立实验服务，运行结果和内存数字未在本次实测。</p><h2 id="position" tabindex="-1">1. 定位：解决什么问题 <a class="header-anchor" href="#position" aria-label="Permalink to &quot;1. 定位：解决什么问题 {#position}&quot;">​</a></h2><p>ZSet 是“带分数、按分数有序的唯一成员集合”。排行榜、评级匹配、在线心跳与延迟任务都可以把排序依据映射成 score。Set 没有排名，List 维护插入顺序，Hash 只能按字段直接查找，三者都不直接提供分数范围查询。</p><h3 id="基本操作示例" tabindex="-1">基本操作示例 <a class="header-anchor" href="#基本操作示例" aria-label="Permalink to &quot;基本操作示例 {#基本操作示例}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ZADD learn:types:rank 10 alice 20 bob</span></span>
<span class="line"><span>ZINCRBY learn:types:rank 5 alice</span></span>
<span class="line"><span>ZRANGE learn:types:rank 0 1 REV WITHSCORES</span></span></code></pre></div><p>预期先返回 <code>bob 20</code>，再返回 <code>alice 15</code>。相同分数会按成员字节顺序进一步排序，倒序会反转这个顺序；如果业务要求“先达到分数的人排前”，需要额外设计规则。</p><p>参考：<a href="https://redis.io/docs/latest/develop/data-types/sorted-sets/" target="_blank" rel="noopener noreferrer">Sorted Set</a>。</p><h3 id="游戏与后端场景" tabindex="-1">游戏与后端场景 <a class="header-anchor" href="#游戏与后端场景" aria-label="Permalink to &quot;游戏与后端场景 {#游戏与后端场景}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>分数与成员</th><th>关键约束</th></tr></thead><tbody><tr><td>在线状态</td><td>score 为最后心跳时间，member 为 uid</td><td>查询前清理超过阈值的成员；在线状态存在检测延迟</td></tr><tr><td>按评级匹配</td><td>score 为 rating，按区间取候选人</td><td>查找、资格校验和移除须原子化；<code>ZPOPMIN</code> 只弹出全局最低分，不表达指定区间</td></tr><tr><td>赛季排行榜</td><td>score 为积分，member 为 uid，键带赛季 ID</td><td>明确并列规则，分数更新是否允许降低</td></tr><tr><td>滑动窗口限流</td><td>score 为请求时刻，member 为唯一请求标识</td><td>清理、计数、添加须原子化；统一时钟与窗口边界</td></tr><tr><td>延迟任务</td><td>score 为执行时刻，member 为任务 ID</td><td>到期取出后消费者崩溃需恢复机制</td></tr><tr><td>热榜</td><td>score 为热度</td><td>衰减和时间窗口需显式设计，不能无限累计旧热度</td></tr></tbody></table><h2 id="commands" tabindex="-1">2. 命令速查与示例 <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;2. 命令速查与示例 {#commands}&quot;">​</a></h2><p>按用途分组，共 <strong>35 项</strong>，覆盖 Redis 8.2.10 的本类型命令及子命令。点击命令名查看官方参数。示例在 redis-cli 中逐行输入，<strong>每次换例子前重置下面的教学数据</strong>。</p><details class="details custom-block"><summary>准备与重置示例数据</summary><p>在独立实验实例的 <strong>redis-cli 交互模式</strong>逐行输入，避免 shell 对引号、<code>&gt;</code>、<code>*</code>、括号等符号进行解释。<strong>每个例子独立使用；换例子前重新执行下面的准备段</strong>，否则删除、弹出、过期和修改操作会影响后续结果。准备段仅重置列出的教学键，确认这些键不承载业务数据。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UNLINK learn:{zset}:a learn:{zset}:b learn:{zset}:lex learn:{zset}:out</span></span>
<span class="line"><span>ZADD learn:{zset}:a 10 alice 20 bob 30 carol</span></span>
<span class="line"><span>ZADD learn:{zset}:b 2 bob 4 dave</span></span>
<span class="line"><span>ZADD learn:{zset}:lex 0 a 0 b 0 c</span></span></code></pre></div><p>示例的返回说明以刚完成准备段为前提，随机结果与剩余 TTL 不固定。带同一 <code>{...}</code> 的教学键便于在 Cluster 中满足相关多键操作的同槽要求。</p></details><h3 id="成员与分数" tabindex="-1">成员与分数 <a class="header-anchor" href="#成员与分数" aria-label="Permalink to &quot;成员与分数 {#成员与分数}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-zadd"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zadd.json" target="_blank" rel="noopener noreferrer">ZADD</a><br>新增或更新分数</td><td><code>ZADD learn:{zset}:a 15 alice 40 dave</code><br>返回新增成员数 1，alice 被更新。</td><td>每个成员 O(log N)</td></tr><tr><td><span id="cmd-zincrby"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zincrby.json" target="_blank" rel="noopener noreferrer">ZINCRBY</a><br>原子加分</td><td><code>ZINCRBY learn:{zset}:a 5 alice</code><br>返回新分数 15。</td><td>O(log N)</td></tr><tr><td><span id="cmd-zscore"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zscore.json" target="_blank" rel="noopener noreferrer">ZSCORE</a><br>读取分数</td><td><code>ZSCORE learn:{zset}:a alice</code><br>返回 10。</td><td>O(1)</td></tr><tr><td><span id="cmd-zmscore"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zmscore.json" target="_blank" rel="noopener noreferrer">ZMSCORE</a><br>批量读取分数</td><td><code>ZMSCORE learn:{zset}:a alice bob missing</code><br>返回 10、20、空值。</td><td>O(M)</td></tr><tr><td><span id="cmd-zcard"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zcard.json" target="_blank" rel="noopener noreferrer">ZCARD</a><br>成员数量</td><td><code>ZCARD learn:{zset}:a</code><br>返回 3。</td><td>O(1)</td></tr><tr><td><span id="cmd-zrandmember"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zrandmember.json" target="_blank" rel="noopener noreferrer">ZRANDMEMBER</a><br>随机读取成员</td><td><code>ZRANDMEMBER learn:{zset}:a 2 WITHSCORES</code><br>读取随机两个不同成员及分数，不删除。</td><td>O(M)</td></tr><tr><td><span id="cmd-zscan"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zscan.json" target="_blank" rel="noopener noreferrer">ZSCAN</a><br>无序游标遍历</td><td><code>ZSCAN learn:{zset}:a 0 COUNT 10</code><br>不是按分数分页，使用返回游标继续。</td><td>单次 O(1)<br>完整 O(N)</td></tr></tbody></table><h3 id="排名与范围" tabindex="-1">排名与范围 <a class="header-anchor" href="#排名与范围" aria-label="Permalink to &quot;排名与范围 {#排名与范围}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-zcount"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zcount.json" target="_blank" rel="noopener noreferrer">ZCOUNT</a><br>分数范围计数</td><td><code>ZCOUNT learn:{zset}:a 10 20</code><br>返回 2。</td><td>O(log N)</td></tr><tr><td><span id="cmd-zlexcount"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zlexcount.json" target="_blank" rel="noopener noreferrer">ZLEXCOUNT</a><br>字典序范围计数</td><td><code>ZLEXCOUNT learn:{zset}:lex [a [b</code><br>同分集合中 a 到 b 共 2 项。</td><td>O(log N)</td></tr><tr><td><span id="cmd-zrank"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zrank.json" target="_blank" rel="noopener noreferrer">ZRANK</a><br>升序名次</td><td><code>ZRANK learn:{zset}:a bob</code><br>返回 1，名次从 0 起。</td><td>O(log N)</td></tr><tr><td><span id="cmd-zrevrank"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zrevrank.json" target="_blank" rel="noopener noreferrer">ZREVRANK</a><br>降序名次</td><td><code>ZREVRANK learn:{zset}:a bob</code><br>返回 1。</td><td>O(log N)</td></tr><tr><td><span id="cmd-zrange"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zrange.json" target="_blank" rel="noopener noreferrer">ZRANGE</a><br>排名、分数或字典序范围查询</td><td><code>ZRANGE learn:{zset}:a 10 20 BYSCORE WITHSCORES</code><br>返回 alice 10、bob 20；默认按排名，没有 BYRANK。</td><td>O(log N+M)</td></tr><tr><td><span id="cmd-zrangestore"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zrangestore.json" target="_blank" rel="noopener noreferrer">ZRANGESTORE</a><br>保存范围查询结果</td><td><code>ZRANGESTORE learn:{zset}:out learn:{zset}:a 0 1</code><br>覆盖 out，保存 alice、bob 并返回 2。</td><td>O(log N+M)</td></tr></tbody></table><h3 id="删除与弹出" tabindex="-1">删除与弹出 <a class="header-anchor" href="#删除与弹出" aria-label="Permalink to &quot;删除与弹出 {#删除与弹出}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-zrem"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zrem.json" target="_blank" rel="noopener noreferrer">ZREM</a><br>删除指定成员</td><td><code>ZREM learn:{zset}:a alice</code><br>返回 1。</td><td>O(M log N)</td></tr><tr><td><span id="cmd-zremrangebyrank"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zremrangebyrank.json" target="_blank" rel="noopener noreferrer">ZREMRANGEBYRANK</a><br>删除名次区间</td><td><code>ZREMRANGEBYRANK learn:{zset}:a 0 1</code><br>删除 alice、bob，返回 2。</td><td>O(log N+M)</td></tr><tr><td><span id="cmd-zremrangebyscore"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zremrangebyscore.json" target="_blank" rel="noopener noreferrer">ZREMRANGEBYSCORE</a><br>删除分数区间</td><td><code>ZREMRANGEBYSCORE learn:{zset}:a -inf 20</code><br>删除分数不超过 20 的两项。</td><td>O(log N+M)</td></tr><tr><td><span id="cmd-zremrangebylex"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zremrangebylex.json" target="_blank" rel="noopener noreferrer">ZREMRANGEBYLEX</a><br>删除字典序区间</td><td><code>ZREMRANGEBYLEX learn:{zset}:lex [a [b</code><br>同分集合删除 a、b，返回 2。</td><td>O(log N+M)</td></tr><tr><td><span id="cmd-zpopmin"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zpopmin.json" target="_blank" rel="noopener noreferrer">ZPOPMIN</a><br>弹出最低分</td><td><code>ZPOPMIN learn:{zset}:a 1</code><br>移除并返回 alice 10。</td><td>O(M log N)</td></tr><tr><td><span id="cmd-zpopmax"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zpopmax.json" target="_blank" rel="noopener noreferrer">ZPOPMAX</a><br>弹出最高分</td><td><code>ZPOPMAX learn:{zset}:a 1</code><br>移除并返回 carol 30。</td><td>O(M log N)</td></tr><tr><td><span id="cmd-zmpop"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zmpop.json" target="_blank" rel="noopener noreferrer">ZMPOP</a><br>从多个集合弹出</td><td><code>ZMPOP 2 learn:{zset}:a learn:{zset}:b MIN COUNT 2</code><br>从首个非空集合 a 弹出两项。</td><td>O(K+M log N)</td></tr><tr><td><span id="cmd-bzpopmin"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/bzpopmin.json" target="_blank" rel="noopener noreferrer">BZPOPMIN</a><br>等待最低分弹出</td><td><code>BZPOPMIN learn:{zset}:a 1</code><br>最多等待 1 秒，准备数据下立即返回 alice。</td><td>O(log N)</td></tr><tr><td><span id="cmd-bzpopmax"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/bzpopmax.json" target="_blank" rel="noopener noreferrer">BZPOPMAX</a><br>等待最高分弹出</td><td><code>BZPOPMAX learn:{zset}:a 1</code><br>准备数据下立即返回 carol。</td><td>O(log N)</td></tr><tr><td><span id="cmd-bzmpop"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/bzmpop.json" target="_blank" rel="noopener noreferrer">BZMPOP</a><br>等待多集合弹出</td><td><code>BZMPOP 1 2 learn:{zset}:a learn:{zset}:b MIN COUNT 2</code><br>最多等待 1 秒，从首个非空集合弹出两项。</td><td>O(K+M log N)</td></tr></tbody></table><h3 id="集合运算" tabindex="-1">集合运算 <a class="header-anchor" href="#集合运算" aria-label="Permalink to &quot;集合运算 {#集合运算}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-zinter"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zinter.json" target="_blank" rel="noopener noreferrer">ZINTER</a><br>有序集合交集</td><td><code>ZINTER 2 learn:{zset}:a learn:{zset}:b WITHSCORES</code><br>bob 同时存在，默认求和后分数为 22。</td><td>最坏 O(Nmin×K+M log M)</td></tr><tr><td><span id="cmd-zintercard"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zintercard.json" target="_blank" rel="noopener noreferrer">ZINTERCARD</a><br>交集成员数</td><td><code>ZINTERCARD 2 learn:{zset}:a learn:{zset}:b</code><br>返回 1。</td><td>最坏 O(Nmin×K)</td></tr><tr><td><span id="cmd-zinterstore"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zinterstore.json" target="_blank" rel="noopener noreferrer">ZINTERSTORE</a><br>保存交集</td><td><code>ZINTERSTORE learn:{zset}:out 2 learn:{zset}:a learn:{zset}:b</code><br>覆盖 out，保存 bob 22，返回 1。</td><td>最坏 O(Nmin×K+M log M)</td></tr><tr><td><span id="cmd-zunion"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zunion.json" target="_blank" rel="noopener noreferrer">ZUNION</a><br>有序集合并集</td><td><code>ZUNION 2 learn:{zset}:a learn:{zset}:b WITHSCORES</code><br>同名成员分数默认求和，不是简单选最大值。</td><td>O(T+M log M)</td></tr><tr><td><span id="cmd-zunionstore"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zunionstore.json" target="_blank" rel="noopener noreferrer">ZUNIONSTORE</a><br>保存并集</td><td><code>ZUNIONSTORE learn:{zset}:out 2 learn:{zset}:a learn:{zset}:b</code><br>覆盖 out，保存 4 个成员。</td><td>O(T+M log M)</td></tr><tr><td><span id="cmd-zdiff"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zdiff.json" target="_blank" rel="noopener noreferrer">ZDIFF</a><br>有序集合差集</td><td><code>ZDIFF 2 learn:{zset}:a learn:{zset}:b WITHSCORES</code><br>返回 alice 10、carol 30。</td><td>最坏 O(T+(N−M) log N)</td></tr><tr><td><span id="cmd-zdiffstore"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zdiffstore.json" target="_blank" rel="noopener noreferrer">ZDIFFSTORE</a><br>保存差集</td><td><code>ZDIFFSTORE learn:{zset}:out 2 learn:{zset}:a learn:{zset}:b</code><br>覆盖 out，返回 2。</td><td>最坏 O(T+(N−M) log N)</td></tr></tbody></table>`,24)])])}const h=t(s,[["render",o]]);export{m as __pageData,h as default};
